/div><aside><section class="section-card"><h2>Disponibilità</h2>${club.players.filter(p=>p.injury||p.bans).map(p=>`<div class="fixture-row"><div>${p.injury?'🩹':'🟥'}</div><div class="fixture-teams"><strong>${p.name}</strong><div class="muted">${p.injury?`Infortunio · ${p.injury} giornate`:`Squalificato · ${p.bans} gara`}</div></div></div>`).join('')||'<div class="muted" style="font-size:11px">Tutti disponibili per la prossima gara.</div>'}</section><section class="section-card"><h2>Indicazioni staff</h2><div class="news-copy">${staffTip(club)}</div><button class="text-link mt-12" onclick="autoLineup()">Schiera i migliori ↗</button></section><section class="section-card"><h2>Regole rosa</h2><div class="muted" style="font-size:10px;line-height:1.7">11 titolari · max 5 sostituzioni durante la gara.<br>Stanchezza e forma si aggiornano a ogni turno.</div></section></aside></div>`}
