 if(m.type==='league'&&!m.fixture.played){
m.fixture.played=true;
m.fixture.score=m.fixture.home===club.id?[own,against]:[against,own];
recordResult(club,own,against);
recordResult(opp,against,own);
game.played++;
game.round++;
game.won+=own>against?1:0;
game.drawn+=own===against?1:0;
game.lost+=own<against?1:0;

  for(const fixture of game.schedule[game.round-1]||[]){
if(fixture===m.fixture||fixture.played)continue;
let h=game.teams.find(t=>t.id===fixture.home),a=game.teams.find(t=>t.id===fixture.away),hg=sampleGoals((h.level-a.level+2)/2),ag=sampleGoals((a.level-h.level-2)/2);
fixture.played=true;
fixture.score=[hg,ag];
recordResult(h,hg,ag);
recordResult(a,ag,hg)}
  game.credits+=own>against?45:own===against?25:12;
settleMatchAvailability(m,club,opp,true);

  game.teams.filter(t=>t!==club).forEach(t=>t.players.forEach(p=>{if(p.injury>0)p.injury--;
if(p.bans>0)p.bans--;
