addNews('⚽',`${game.club} supera ${opp.name} ${own}–${against} e sale in classifica.`,'social')}
else if(own<against)addNews('⚽',`${game.club} cade contro ${opp.name}: ${own}–${against}. La pressione aumenta.`,'social');
else addNews('🤝',`${game.club} pareggia ${own}–${against} contro ${opp.name}.`,'social');

  if(game.round===9&&game.window==='estiva'){
