### settleCupMatch ###
function settleCupMatch(m,own,against){
let c=ensureCup(),pair=m.cupPair||c.rounds[c.round]?.find(x=>x.a===currentClub().id||x.b===currentClub().id);
if(!pair||pair.done)return;
let userWon=own===against?Math.random()>.5:own>against,winner=userWon?currentClub().id:m.oppId;
pair.done=true;
pair.winner=winner;
pair.score=[own,against];
let name=id=>game.teams.find(t=>t.id===id)?.name||id;
for(const other of c.rounds[c.round]){
if(other.done)continue;
let a=game.teams.find(t=>t.id===other.a),b=game.teams.find(t=>t.id===other.b),x=sampleGoals((a.level-b.level)/2),y=sampleGoals((b.level-a.level)/2);
if(x===y)x++;
other.score=[x,y];
other.winner=x>y?a.id:b.id;
other.done=true}
 c.results[c.round]=c.rounds[c.round].map(x=>`${name(x.a)} ${x.score[0]}–${x.score[1]} ${name(x.b)} · ${name(x.winner)} passa`);
if(c.round===2){
c.done=true;
c.champion=name(c.rounds[2][0].winner);
if(c.champion===game.club){
game.trophies++;
game.prestige=Math.min(5,game.prestige+1);
game.credits+=200;
game.reputation=Math.min(100,game.reputation+8);
addNews('🏆',`${game.club} conquista la Coppa Italia Serie C!`,'club')}
else addNews('🏆',`${c.champion} vince la Coppa Italia Serie C.`,'world')}
else{let winners=c.rounds[c.round].map(x=>x.winner);
c.round++;
c.rounds[c.round]=Array.from({length:winners.length/2},(_,i)=>({a:winners[i*2],b:winners[i*2+1]}))}save()}

### ensureCup ###
function ensureCup(){
let c=game.cup;
if(c.rounds)return c;
let entrants=game.teams.slice().sort(()=>Math.random()-.5).slice(0,8);
if(!entrants.includes(currentClub()))entrants[0]=currentClub();
c.entrants=entrants.map(t=>t.id);
c.round=0;
c.rounds=[Array.from({length:4},(_,i)=>({a:c.entrants[i*2],b:c.entrants[i*2+1]}))];
c.results=[];
c.done=false;
return c}

