### openCupMatch ###
function openCupMatch(){let c=ensureCup();
if(c.done)return toast('La Coppa è già conclusa.');
if(c.round>=3)return toast('Turno non disponibile.');
let pair=c.rounds[c.round]?.find(x=>x.a===currentClub().id||x.b===currentClub().id);
if(!pair)return toast('La tua squadra è stata eliminata dalla Coppa.');
if(pair.done)return toast('Questo turno è già stato giocato.');
let opp=game.teams.find(t=>t.id===(pair.a===currentClub().id?pair.b:pair.a));
game.match=buildMatch('cup',opp,null);
game.match.cupPair=pair;
matchMode='normal';
save();
render()}

